macro_rules! deps {
    () => {
        Error!();
    };
}

macro_rules! function {
    () => {
        deps!();
        pub (crate) mod function { use std :: path :: { Component :: { CurDir , Normal , ParentDir , Prefix , RootDir } , Path , PathBuf , } ; use super :: Error ; use crate :: realpath :: MAX_SYMLINKS ; # [doc = " Check each component of `path` and see if it is a symlink. If so, resolve it."] # [doc = " Do not fail for non-existing components, but assume these are as is."] # [doc = ""] # [doc = " If `path` is relative, the current working directory be used to make it absolute."] # [doc = " Note that the returned path will be verbatim, and repositories with `core.precomposeUnicode`"] # [doc = " set will probably want to precompose the paths unicode."] pub fn realpath (path : impl AsRef < Path >) -> Result < PathBuf , Error > { let path = path . as_ref () ; let cwd = path . is_relative () . then (std :: env :: current_dir) . unwrap_or_else (| | Ok (PathBuf :: default ())) . map_err (Error :: CurrentWorkingDir) ? ; realpath_opts (path , & cwd , MAX_SYMLINKS) } # [doc = " The same as [`realpath()`], but allow to configure `max_symlinks` to configure how many symbolic links we are going to follow."] # [doc = " This serves to avoid running into cycles or doing unreasonable amounts of work."] pub fn realpath_opts (path : & Path , cwd : & Path , max_symlinks : u8) -> Result < PathBuf , Error > { if path . as_os_str () . is_empty () { return Err (Error :: EmptyPath) ; } let mut real_path = PathBuf :: new () ; if path . is_relative () { real_path . push (cwd) ; } let mut num_symlinks = 0 ; let mut path_backing : PathBuf ; let mut components = path . components () ; const MAX_SYMLINK_CHECKS : usize = 2048 ; let mut symlink_checks = 0 ; while let Some (component) = components . next () { match component { part @ (RootDir | Prefix (_)) => real_path . push (part) , CurDir => { } ParentDir => { if ! real_path . pop () { return Err (Error :: MissingParent) ; } } Normal (part) => { real_path . push (part) ; symlink_checks += 1 ; if real_path . is_symlink () { num_symlinks += 1 ; if num_symlinks > max_symlinks { return Err (Error :: MaxSymlinksExceeded { max_symlinks }) ; } let mut link_destination = std :: fs :: read_link (real_path . as_path ()) . map_err (Error :: ReadLink) ? ; if link_destination . is_absolute () { } else { assert ! (real_path . pop () , "we just pushed a component") ; } link_destination . extend (components) ; path_backing = link_destination ; components = path_backing . components () ; } if symlink_checks > MAX_SYMLINK_CHECKS { return Err (Error :: ExcessiveComponentCount { max_symlink_checks : MAX_SYMLINK_CHECKS , }) ; } } } } Ok (real_path) } }
    };
}

function!()